effectSpeciesRank.Text+"」 범위의 「"+(int)effectSpeciesValue.Value+"」까지 내린다.";else if(effectAction.Text=="지정 등급으로 변경")effectPreview.Text=target+"를 「"+effectSpeciesRank.Text+"」 범위의 「"+(int)effectSpeciesValue.Value+"」로 한다.";else effectPreview.Text=target+"를 「"+(int)effectSpeciesValue.Value+"」로 한다.";}else if(switchEffect)effectPreview.Text=EffectNormalizer.CanonicalSwitch();else if(pivotEffect)effectPreview.Text=EffectNormalizer.CanonicalPivotGrant();else if(switchRestriction)effectPreview.Text=EffectNormalizer.CanonicalSwitchRestriction();else if(analysis)effectPreview.Text=EffectNormalizer.CanonicalAnalysisPermission();else if(scalar){effectPreview.Text=EffectNormalizer.Canonical(effectTarget.Text,effectAction.Text=="약화"?"약화":"강화",(double)effectRate.Value);}else if(fraction){string target=new[]{"자신","상대","아군 1체","아군 전체"}.Contains(effectTarget.Text)?effectTarget.Text:"자신";int n=(int)effectDenominator.Value;effectPreview.Text=effectAction.Text=="대미지"?target+"에게 최대 HP의 1/"+n+" 대미지를 준다."+(effectCanFaint.Checked?"":" 이 대미지로는 빈사로 할 수 없다."):target+"의 체력을 최대 HP의 1/"+n+" 회복한다.";}else if(rank){if(effectDenominator.Value>3)effectDenominator.Value=3;effectPreview.Text=EffectNormalizer.CanonicalRank(effectTarget.Text,(effectAction.Text=="하락"?-1:1)*(int)effectDenominator.Value);}else if(priority){effectPreview.Text=EffectNormalizer.CanonicalPriority(effectTarget.Text,(effectAction.Text=="하락"?-1:1)*(int)effectDenominator.Value);}else effectPreview.Text="";effectPreview.Text=EffectNormalizer.WithProbability(effectProbability==null?"":effectProbability.Text,effectPreview.Text);effectKind.Invalidate();effectAction.Invalidate();}
